<?php
namespace App\Console\Commands; use App\Services\Dapcode\AegisguardLoader; use App\Services\Dapcode\IntegrityService; use App\Services\Dapcode\LicenseGuard; use Illuminate\Console\Command; use Illuminate\Support\Str; class DapcodeAegisguardDecryptCommand extends Command { protected $signature = 'dapcode:aegisguard-decrypt {--force : Force decryption without interactive confirmation}'; protected $aliases = ['aegisguard:decrypt', 'dapcode:unenc-aegisguard']; protected $description = 'Decrypt and restore AegisGuard core code files from .enc envelopes to original readable source code'; public function __construct() { parent::__construct(); $this->setAliases(['aegisguard:decrypt', 'dapcode:unenc-aegisguard']); } public function handle() { $this->info("======================================================="); $this->info("   DAPCODE AEGISGUARD — CORE CODE DECRYPTION ENGINE     "); $this->info("======================================================="); $this->line("Mendekripsi seluruh file kode proteksi AegisGuard dari format .enc ke kode sumber asli..."); $this->newLine(); $files = AegisguardLoader::getTargetAegisguardFiles(); if (empty($files)) { $this->error("Tidak ada file kode AegisGuard yang ditemukan."); return 1; } $force = (bool) $this->option('force'); if ( ! $force && $this->input->isInteractive()) { if ( ! $this->confirm("Apakah Anda yakin ingin mendekripsi seluruh file kode AegisGuard ke kode sumber asli?", true)) { $this->warn("Operasi dibatalkan oleh pengguna."); return 0; } } $bar = $this->output->createProgressBar(count($files)); $bar->start(); $results = []; $restoredCount = 0; foreach ($files as $file) { $res = AegisguardLoader::decryptFile($file); $relPath = str_replace('\\', '/', Str::after($file, base_path() . DIRECTORY_SEPARATOR)); if ($res['success']) { $statusLabel = ! empty($res['already_plain']) ? '<comment>📄 SUDAH DECRYPTED</comment>' : '<info>✓ BERHASIL DIDEKRIPSI</info>'; if (empty($res['already_plain'])) { $restoredCount++; } $results[] = [ 'file' => $relPath, 'status' => $statusLabel, 'size' => $this->formatBytes(filesize($file)), ]; } else { $results[] = [ 'file' => $relPath, 'status' => '<error>GAGAL: ' . ($res['message'] ?? 'Error') . '</error>', 'size' => '-', ]; } $bar->advance(); } $bar->finish(); $this->newLine(2); $this->table( ['File Target', 'Status', 'Ukuran Kode'], $results ); IntegrityService::recordCoreFilesManifest(); LicenseGuard::clearCache(); $this->callSilently('config:clear'); $this->info("======================================================="); $this->info(" [SELESAI] {$restoredCount} file kode AegisGuard berhasil didekripsi & dipulihkan!"); $this->line(" Status: Seluruh kode sumber siap untuk di-edit, di-debug, atau di-maintain."); $this->info("======================================================="); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }